use std::collections::BTreeMap;
use std::fs::{self, create_dir};
use std::path::{Path, PathBuf};

use anyhow::anyhow;
use crate::lib_type::LibType;
use crate::targets::ApplePlatform;
use crate::Result;
use camino::{Utf8Path, Utf8PathBuf};
use uniffi_bindgen::bindings::{GenerateOptions, TargetLanguage};

use crate::recreate_dir;

/// A C module generated by UniFFI for a single crate.
struct FfiModule {
    /// Module name as declared in the modulemap (`ffi_module_name`).
    name: String,
    /// Header file name referenced by the modulemap (`ffi_module_filename`).
    header: String,
    /// Contents of the modulemap generated by UniFFI.
    modulemap: String,
}

impl FfiModule {
    fn parse(modulemap: String) -> Result<Self> {
        let name = modulemap
            .lines()
            .find_map(|line| line.trim().strip_prefix("module "))
            .and_then(|rest| rest.split_whitespace().next())
            .ok_or_else(|| anyhow!("Could not find module name in modulemap:\n{modulemap}"))?
            .to_owned();
        let header = modulemap
            .lines()
            .find_map(|line| line.trim().strip_prefix("header "))
            .map(|rest| rest.trim().trim_matches('"').to_owned())
            .ok_or_else(|| anyhow!("Could not find header in modulemap:\n{modulemap}"))?;

        Ok(Self {
            name,
            header,
            modulemap,
        })
    }
}

/// Directory containing the generated headers for the given platform.
pub fn platform_headers_dir(generated_dir: &Path, platform: ApplePlatform) -> PathBuf {
    generated_dir.join(platform.identifier()).join("headers")
}

/// Generates UniFFI bindings for every platform and returns the FFI module name.
///
/// Bindings are generated separately from each platform's library, since the exported
/// API may differ between platforms (e.g. items gated behind `#[cfg(target_os = "ios")]`).
/// Headers are kept per platform in `generated/<platform>/headers` and end up in the
/// matching XCFramework slice.
///
/// Swift sources are written to `generated/sources`. A Swift package target cannot select
/// source files per platform, so a file that differs between platforms is split into files
/// wrapped in `#if` blocks:
/// - `<name>.swift` when identical for all platforms,
/// - `<name>.<os>.swift` when identical for all platforms of an OS (e.g. device and simulator),
/// - `<name>.<platform>.swift` otherwise.
pub fn generate_bindings(
    platform_libs: &[(ApplePlatform, Utf8PathBuf)],
    lib_type: LibType,
) -> Result<String> {
    let out_dir = Utf8Path::new("./generated");
    let sources = out_dir.join("sources");

    recreate_dir(out_dir)?;
    create_dir(&sources)?;

    let mut ffi_module_name: Option<String> = None;
    // File name -> list of (platform, content generated for that platform)
    let mut swift_files = BTreeMap::<String, Vec<(ApplePlatform, String)>>::new();

    for (platform, lib_path) in platform_libs {
        let platform_dir = out_dir.join(platform.identifier());
        let platform_module_name = generate_platform_bindings(lib_path, lib_type, &platform_dir)?;

        match &ffi_module_name {
            None => ffi_module_name = Some(platform_module_name),
            Some(name) if *name != platform_module_name => {
                return Err(anyhow!(
                    "FFI module name differs between platforms: {name} and {platform_module_name}"
                )
                .into())
            }
            Some(_) => {}
        }

        for f in fs::read_dir(platform_dir.join("sources"))? {
            let path = f?.path();
            let file_name = path.file_name().unwrap().to_string_lossy().to_string();
            let content = fs::read_to_string(&path)?;

            swift_files
                .entry(file_name)
                .or_default()
                .push((*platform, content));
        }
    }

    for (file_name, variants) in swift_files {
        let (_, first) = &variants[0];
        if variants.len() == platform_libs.len() && variants.iter().all(|(_, c)| c == first) {
            fs::write(sources.join(&file_name), first)?;
            continue;
        }

        let stem = file_name.strip_suffix(".swift").unwrap_or(&file_name);
        let write_variant = |suffix: &str, condition: &str, content: &str| {
            fs::write(
                sources.join(format!("{stem}.{suffix}.swift")),
                format!("#if {condition}\n{content}\n#endif\n"),
            )
        };

        // Platforms of the same OS (e.g. device and simulator) usually generate identical
        // code, in which case they share a single file.
        let mut os_families = Vec::new();
        for (platform, _) in platform_libs {
            if !os_families.contains(&platform.os_family()) {
                os_families.push(platform.os_family());
            }
        }

        for (os, os_condition) in os_families {
            let os_platforms = platform_libs
                .iter()
                .filter(|(platform, _)| platform.os_family().0 == os)
                .count();
            let os_variants: Vec<_> = variants
                .iter()
                .filter(|(platform, _)| platform.os_family().0 == os)
                .collect();

            match os_variants.as_slice() {
                [] => {}
                [(_, first), ..]
                    if os_variants.len() == os_platforms
                        && os_variants.iter().all(|(_, c)| c == first) =>
                {
                    write_variant(os, os_condition, first)?;
                }
                _ => {
                    for (platform, content) in os_variants {
                        write_variant(platform.identifier(), platform.swift_condition(), content)?;
                    }
                }
            }
        }
    }

    ffi_module_name.ok_or_else(|| anyhow!("No platforms to generate bindings for").into())
}

/// Generates UniFFI bindings for a single platform library into `out_dir` and returns
/// the FFI module name.
///
/// This function respects the `ffi_module_name` and `ffi_module_filename` settings
/// in uniffi.toml. The returned FFI module name is detected from the generated
/// header files, which reflect whatever is configured in uniffi.toml.
///
/// When the library exposes multiple crates, UniFFI generates one FFI module per crate.
/// For static libraries, each module gets its own `headers/<module>/` directory so that
/// clang can resolve every module by name. A dynamic library is wrapped in a single
/// framework that can only expose one module, so all headers are merged into the primary
/// FFI module and the generated Swift sources are rewritten to import it instead.
fn generate_platform_bindings(
    lib_path: &Utf8Path,
    lib_type: LibType,
    out_dir: &Utf8Path,
) -> Result<String> {
    let headers = out_dir.join("headers");
    let sources = out_dir.join("sources");

    create_dir(out_dir)?;
    create_dir(&headers)?;
    create_dir(&sources)?;

    let options = GenerateOptions {
        languages: vec![TargetLanguage::Swift],
        source: lib_path.to_path_buf(),
        out_dir: out_dir.to_path_buf(),
        metadata_no_deps: true,
        ..Default::default()
    };
    uniffi_bindgen::bindings::generate(options)?;

    // Detect the FFI module name from the generated header file.
    // This respects ffi_module_name/ffi_module_filename from uniffi.toml.
    let ffi_module_name = fs::read_dir(out_dir)?
        .filter_map(|entry| entry.ok())
        .find(|entry| {
            entry.path().extension().is_some_and(|ext| ext == "h")
                && entry
                    .path()
                    .file_stem()
                    .is_some_and(|stem| !stem.to_string_lossy().contains("BridgingHeader"))
        })
        .ok_or_else(|| anyhow!("Could not find generated header file in {}", out_dir))?
        .path()
        .file_stem()
        .unwrap()
        .to_string_lossy()
        .to_string();

    let mut modules = Vec::new();
    let mut swift_files = Vec::new();

    for f in fs::read_dir(out_dir)? {
        let f = f?;
        if !f.metadata()?.is_file() {
            continue;
        }

        let file_path = Utf8PathBuf::try_from(f.path()).map_err(anyhow::Error::from)?;
        match file_path.extension() {
            Some("swift") => swift_files.push(file_path),
            Some("modulemap") => modules.push(FfiModule::parse(fs::read_to_string(&file_path)?)?),
            _ => {}
        }
    }

    let primary = modules
        .iter()
        .position(|module| Utf8Path::new(&module.header).file_stem() == Some(&ffi_module_name))
        .ok_or_else(|| anyhow!("Could not find modulemap for FFI module {ffi_module_name}"))?;
    let primary = modules.swap_remove(primary);

    match lib_type {
        LibType::Static => {
            for module in std::iter::once(&primary).chain(&modules) {
                let module_dir = headers.join(&module.name);
                create_dir(&module_dir)?;
                fs::copy(
                    out_dir.join(&module.header),
                    module_dir.join(&module.header),
                )?;
                fs::write(module_dir.join("module.modulemap"), &module.modulemap)?;
            }
        }
        LibType::Dynamic => {
            let mut header_lines = Vec::new();
            for module in std::iter::once(&primary).chain(&modules) {
                fs::copy(out_dir.join(&module.header), headers.join(&module.header))?;
                header_lines.push(format!("header \"{}\"", module.header));
            }

            let primary_header_line = format!("header \"{}\"", primary.header);
            let modulemap =
                primary
                    .modulemap
                    .replacen(&primary_header_line, &header_lines.join("\n    "), 1);
            fs::write(headers.join("module.modulemap"), modulemap)?;
        }
    }

    for file_path in swift_files {
        let mut source = fs::read_to_string(&file_path)?;
        if lib_type == LibType::Dynamic {
            for module in &modules {
                source = source
                    .replace(
                        &format!("canImport({})", module.name),
                        &format!("canImport({})", primary.name),
                    )
                    .replace(
                        &format!("import {}\n", module.name),
                        &format!("import {}\n", primary.name),
                    );
            }
        }
        fs::write(sources.join(file_path.file_name().unwrap()), source)?;
    }

    Ok(ffi_module_name)
}
